// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/black-han-sans";
import "@fontsource/noto-sans-kr";
import "@fontsource/orbitron";

export const blackHanSans = { variable: "" };
export const notoSansKR = { variable: "" };
export const orbitron = { variable: "" };

"use client";

import { useEffect, type RefObject } from "react";

/**
 * Pointer parallax for the NEON street scene. Writes normalized pointer
 * offsets (-0.5 → 0.5) to `--neon-px` / `--neon-py` on the referenced stage,
 * so the skyline, hanging signs, and puddle reflections drift at different
 * depths as you move. Pure input→style mapping (no animation loop), so it
 * stays live under reduced motion — only the *drift* is disabled there, the
 * scene still composes statically.
 *
 * Pointer is optional: with no pointer (touch), the scene simply sits at its
 * resting position — every layer is designed to look complete at 0,0.
 */
export function usePointerParallax(
  ref: RefObject<HTMLElement | null>,
  disabled: boolean,
): void {
  useEffect(() => {
    if (disabled) return;
    const el = ref.current;
    if (!el) return;

    const onMove = (ev: PointerEvent) => {
      const rect = el.getBoundingClientRect();
      const x = (ev.clientX - rect.left) / rect.width - 0.5;
      const y = (ev.clientY - rect.top) / rect.height - 0.5;
      el.style.setProperty("--neon-px", x.toFixed(3));
      el.style.setProperty("--neon-py", y.toFixed(3));
    };

    window.addEventListener("pointermove", onMove, { passive: true });
    return () => window.removeEventListener("pointermove", onMove);
  }, [ref, disabled]);
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

/* ==========================================================================
   NEON 네온 — rain-slick cyberpunk city · 2087 · District 9
   vaporwave · rain-black / magenta / cyan / purple / amber
   neon glow + falling rain + scanlines + retrowave grid. Pure code.
   Scoped by convention to .neon-root; classes prefixed neon-.
   ========================================================================== */

.neon-root {
  --neon-bg: #0a0612;
  --neon-deep: #05030a;
  --neon-night: #160a2e;
  --neon-magenta: #ff2d95;
  --neon-cyan: #00f0ff;
  --neon-purple: #b026ff;
  --neon-amber: #ffb000;
  --neon-sign-white: #f0f0ff;
  --neon-dim: #6b4a7a;
  --neon-quiet: #4a3357;

  --neon-font-display: var(--font-black-han), "Black Han Sans", sans-serif;
  --neon-font-kr: "Noto Sans KR", sans-serif;
  --neon-font-latin: "Orbitron", sans-serif;
  --neon-font-stack: "Orbitron", "Noto Sans KR", sans-serif;

  --neon-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --px: var(--neon-px, 0);
  --py: var(--neon-py, 0);

  position: relative;
  min-height: 100vh;
  background: var(--neon-bg);
  background-image: linear-gradient(
    180deg,
    var(--neon-deep) 0%,
    var(--neon-bg) 55%,
    var(--neon-night) 100%
  );
  color: var(--neon-sign-white);
  font-family: var(--neon-font-stack);
  font-weight: 400;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  overflow-x: clip;
}

.neon-root :lang(ko) {
  font-family: var(--neon-font-kr);
}

.neon-root ::selection {
  background: var(--neon-magenta);
  color: var(--neon-bg);
}

.neon-root :focus-visible {
  outline: 2px solid var(--neon-cyan);
  outline-offset: 4px;
}

.neon-doc {
  position: relative;
  z-index: 2;
}

.neon-visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ---- Reveal gating (JS-dependent pre-states) ---- */
.neon-js [data-reveal] {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 800ms var(--neon-ease), transform 800ms var(--neon-ease);
}
.neon-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .neon-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

/* ==========================================================================
   Hero — the title bleeding through rain
   ========================================================================== */
.neon-hero {
  position: relative;
  padding: clamp(80px, 16vh, 150px) clamp(20px, 5vw, 60px) clamp(40px, 7vh, 72px);
  text-align: center;
}
.neon-kicker {
  font-family: var(--neon-font-latin);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--neon-cyan);
  margin: 0 0 clamp(28px, 5vh, 48px);
  text-shadow: 0 0 8px rgba(0, 240, 255, 0.6);
}
.neon-title {
  font-family: var(--neon-font-latin);
  font-weight: 900;
  font-size: clamp(4.5rem, 18vw, 14rem);
  line-height: 0.88;
  margin: 0 0 clamp(18px, 3vh, 28px);
  letter-spacing: -0.01em;
  text-align: center;
}
/* The wordmark as four separate neon tubes — each letter is a real sign:
   a bright white-glass core, a saturated gas glow, a wide outer bloom, and
   a thin tube outline. Tubes flicker on mutually-prime periods. */
.neon-tubes {
  display: inline-flex;
  gap: 0.04em;
}
.neon-tube {
  display: inline-block;
  /* white-hot core, the glass tube itself — bright enough to read on the
     darkest night, with the gas glow carried by text-shadow. */
  color: #ffffff;
  text-shadow:
    0 0 2px #fff;
}
.neon-tube--magenta {
  text-shadow:
    0 0 4px #fff,
    0 0 10px var(--neon-magenta),
    0 0 24px var(--neon-magenta),
    0 0 48px rgba(255, 45, 149, 0.7),
    0 0 90px rgba(255, 45, 149, 0.4);
  animation: neon-flicker-a 4.1s infinite;
}
.neon-tube--cyan {
  text-shadow:
    0 0 4px #fff,
    0 0 10px var(--neon-cyan),
    0 0 24px var(--neon-cyan),
    0 0 48px rgba(0, 240, 255, 0.7),
    0 0 90px rgba(0, 240, 255, 0.4);
}
.neon-tube--purple {
  text-shadow:
    0 0 4px #fff,
    0 0 10px var(--neon-purple),
    0 0 24px var(--neon-purple),
    0 0 48px rgba(176, 38, 255, 0.7),
    0 0 90px rgba(176, 38, 255, 0.4);
  animation: neon-flicker-c 5.7s infinite;
}
.neon-title__kr {
  display: block;
  font-family: var(--neon-font-display);
  font-size: 0.26em;
  color: #fff;
  -webkit-text-stroke: 1px rgba(0, 240, 255, 0.5);
  paint-order: stroke fill;
  text-shadow:
    0 0 3px #fff,
    0 0 8px var(--neon-cyan),
    0 0 18px var(--neon-cyan),
    0 0 36px rgba(0, 240, 255, 0.6);
  margin-top: 16px;
  letter-spacing: 0.12em;
}
@media (prefers-reduced-motion: reduce) {
  .neon-tube, .neon-title__kr { animation: none; }
}

/* Wet-asphalt reflection — the sign mirrored, faded and smeared downward,
   the puddle every neon sign stands in. */
.neon-title__reflect {
  display: flex;
  justify-content: center;
  gap: 0.04em;
  font-family: var(--neon-font-latin);
  font-weight: 900;
  font-size: clamp(4.5rem, 18vw, 14rem);
  line-height: 0.5;
  margin-top: 0.1em;
  transform: scaleY(-1);
  opacity: 0.22;
  filter: blur(2px);
  -webkit-mask: linear-gradient(180deg, #000 0%, transparent 55%);
  mask: linear-gradient(180deg, #000 0%, transparent 55%);
  pointer-events: none;
  user-select: none;
}
.neon-title__reflect .neon-tube {
  font-size: 1em;
  -webkit-text-stroke: 0;
}
.neon-sub {
  color: var(--neon-dim);
  font-size: clamp(0.92rem, 1.6vw, 1.12rem);
  margin: 0 auto clamp(28px, 5vh, 44px);
  max-width: 40ch;
}
.neon-sub :lang(ko) { color: var(--neon-quiet); }
.neon-hero__cue {
  font-family: var(--neon-font-latin);
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--neon-purple);
  margin: 0;
  opacity: 0.85;
}

/* ==========================================================================
   The street scene — skyline, puddle, hanging signs. Pointer parallax.
   ========================================================================== */
.neon-scene {
  position: relative;
  height: clamp(360px, 60vh, 600px);
  margin: 0 clamp(8px, 2vw, 24px);
  overflow: hidden;
  border-top: 1px solid rgba(176, 38, 255, 0.22);
  border-bottom: 1px solid rgba(176, 38, 255, 0.22);
  /* the wet night sky behind the buildings */
  background:
    radial-gradient(120% 80% at 50% 0%, rgba(176, 38, 255, 0.18), transparent 60%),
    linear-gradient(180deg, #1a0a2e 0%, #0a0612 70%, #05030a 100%);
  box-shadow: inset 0 0 120px rgba(0, 0, 0, 0.6);
}

/* The generated rain-city render — the real Blade-Runner metropolis behind
   the CSS skyline. Re-tinted toward the entry's neon palette (magenta +
   cyan) so the source render's default indigo/violet — an AI-template tell —
   is suppressed; darkened so code buildings + hanging signs read in front. */
.neon-scene__city {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 40%;
  opacity: 0.38;
  filter: hue-rotate(290deg) saturate(1.4) brightness(0.55) contrast(1.1);
  z-index: 0;
  pointer-events: none;
}
.neon-skyline { position: relative; z-index: 1; }

.neon-skyline {
  position: absolute;
  inset: 0 0 26% 0;
}
.neon-bldg {
  position: absolute;
  bottom: 0;
  background:
    /* faint window grid inside each building face */
    repeating-linear-gradient(90deg, transparent 0 14px, rgba(0,0,0,0.5) 14px 15px),
    repeating-linear-gradient(0deg, transparent 0 18px, rgba(0,0,0,0.45) 18px 19px),
    linear-gradient(180deg, #241144 0%, #14082a 60%, #0a0612 100%);
  border-top: 2px solid rgba(0, 240, 255, 0.25);
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.7), 0 0 18px rgba(176, 38, 255, 0.15);
}
.neon-bldg--1 { left: 0%;   width: 16%; height: 78%; transform: translateX(calc(var(--px) * -8px)); }
.neon-bldg--2 { left: 13%;  width: 20%; height: 96%; transform: translateX(calc(var(--px) * -14px)); }
.neon-bldg--3 { left: 31%;  width: 14%; height: 64%; transform: translateX(calc(var(--px) * -20px)); }
.neon-bldg--4 { left: 43%;  width: 22%; height: 88%; transform: translateX(calc(var(--px) * -10px)); }
.neon-bldg--5 { left: 63%;  width: 18%; height: 72%; transform: translateX(calc(var(--px) * 12px)); }
.neon-bldg--6 { left: 79%;  width: 21%; height: 92%; transform: translateX(calc(var(--px) * 18px)); }

/* lit windows — scattered specks of warm/cold light */
.neon-win {
  position: absolute;
  width: 4px;
  height: 5px;
  background: var(--neon-amber);
  box-shadow: 0 0 6px var(--neon-amber);
  opacity: 0.7;
  animation: neon-win-blink 5.7s infinite;
}
.neon-win--a { left: 5%;  bottom: 40%; animation-delay: 0s; }
.neon-win--b { left: 18%; bottom: 62%; background: var(--neon-cyan); box-shadow: 0 0 6px var(--neon-cyan); animation-delay: 1.4s; }
.neon-win--c { left: 36%; bottom: 30%; animation-delay: 2.6s; }
.neon-win--d { left: 50%; bottom: 58%; background: var(--neon-magenta); box-shadow: 0 0 6px var(--neon-magenta); animation-delay: 0.8s; }
.neon-win--e { left: 70%; bottom: 44%; animation-delay: 3.3s; }
.neon-win--f { left: 86%; bottom: 66%; background: var(--neon-cyan); box-shadow: 0 0 6px var(--neon-cyan); animation-delay: 2.1s; }

.neon-puddle {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 26%;
  background:
    linear-gradient(180deg, rgba(176, 38, 255, 0.10) 0%, rgba(10, 6, 18, 0.5) 30%, #05030a 100%);
  overflow: hidden;
  border-top: 1px solid rgba(0, 240, 255, 0.15);
}
.neon-puddle__refl {
  position: absolute;
  bottom: 25%;
  filter: blur(10px);
  opacity: 0.8;
  transform: scaleY(-1) translateX(calc(var(--px) * 6px));
}
.neon-puddle__refl--magenta {
  left: 12%;
  width: 120px;
  height: 150px;
  background: radial-gradient(circle, var(--neon-magenta) 0%, transparent 70%);
}
.neon-puddle__refl--cyan {
  right: 16%;
  width: 140px;
  height: 170px;
  background: radial-gradient(circle, var(--neon-cyan) 0%, transparent 70%);
}

/* hanging vertical neon signs off the building faces */
.neon-hang {
  position: absolute;
  top: 8%;
  writing-mode: vertical-rl;
  font-family: var(--neon-font-display);
  font-size: clamp(1.4rem, 3vw, 2.4rem);
  padding: 10px 8px;
  border: 1px solid currentColor;
  border-radius: 2px;
  transform: translateY(calc(var(--py) * -10px));
}
.neon-hang--magenta {
  left: 22%;
  color: var(--neon-magenta);
  text-shadow: 0 0 8px var(--neon-magenta), 0 0 18px rgba(255, 45, 149, 0.5);
  box-shadow: 0 0 14px rgba(255, 45, 149, 0.3), inset 0 0 10px rgba(255, 45, 149, 0.15);
  animation: neon-flicker-b 3.2s infinite;
}
.neon-hang--cyan {
  right: 26%;
  color: var(--neon-cyan);
  text-shadow: 0 0 8px var(--neon-cyan), 0 0 18px rgba(0, 240, 255, 0.5);
  box-shadow: 0 0 14px rgba(0, 240, 255, 0.3), inset 0 0 10px rgba(0, 240, 255, 0.15);
}
.neon-hang--purple {
  right: 8%;
  top: 18%;
  color: var(--neon-purple);
  font-family: var(--neon-font-latin);
  font-weight: 900;
  text-shadow: 0 0 8px var(--neon-purple), 0 0 18px rgba(176, 38, 255, 0.5);
  box-shadow: 0 0 14px rgba(176, 38, 255, 0.3), inset 0 0 10px rgba(176, 38, 255, 0.15);
  animation: neon-flicker-c 5.7s infinite;
}

/* ==========================================================================
   Holographic marquee — the storefront ticker
   ========================================================================== */
.neon-marquee {
  overflow: hidden;
  padding: 16px 0;
  border-top: 1px solid rgba(176, 38, 255, 0.22);
  border-bottom: 1px solid rgba(176, 38, 255, 0.22);
  white-space: nowrap;
  background: linear-gradient(90deg, rgba(5,3,10,0.6), rgba(22,10,46,0.4), rgba(5,3,10,0.6));
}
.neon-marquee__track {
  display: inline-block;
  font-family: var(--neon-font-latin);
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  color: var(--neon-cyan);
  text-shadow: 0 0 6px rgba(0, 240, 255, 0.6);
  animation: neon-marquee 30s linear infinite;
  padding-left: 100%;
}
.neon-marquee__track :lang(ko) { color: var(--neon-magenta); text-shadow: 0 0 6px rgba(255,45,149,0.6); }
@keyframes neon-marquee { to { transform: translateX(-50%); } }
@media (prefers-reduced-motion: reduce) {
  .neon-marquee__track { animation: none; padding-left: 0; }
}

/* ==========================================================================
   Section heading — shared
   ========================================================================== */
.neon-sechead {
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(64px, 11vh, 120px) clamp(20px, 5vw, 60px) clamp(28px, 4vh, 44px);
}
.neon-sechead--center { text-align: center; }
.neon-eyebrow {
  font-family: var(--neon-font-latin);
  font-size: 0.7rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--neon-amber);
  margin: 0 0 14px;
  text-shadow: 0 0 6px rgba(255, 176, 0, 0.4);
}
.neon-secthead__title {
  font-family: var(--neon-font-latin);
  font-weight: 900;
  font-size: clamp(2rem, 5vw, 4rem);
  line-height: 1;
  letter-spacing: -0.01em;
  margin: 0 0 14px;
  color: var(--neon-sign-white);
  text-shadow: 0 0 18px rgba(240, 240, 255, 0.2);
}
.neon-secthead__kr {
  font-family: var(--neon-font-display);
  font-size: clamp(0.95rem, 1.8vw, 1.2rem);
  color: var(--neon-dim);
  margin: 0;
  max-width: 36ch;
}
.neon-secthead__kr--center { margin-inline: auto; }

/* ==========================================================================
   Sign gallery — the storefronts (ASCII neon, flickering glow)
   ========================================================================== */
.neon-signgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: clamp(20px, 3vw, 40px);
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 clamp(20px, 5vw, 60px) clamp(60px, 10vh, 100px);
}
.neon-sign {
  text-align: center;
  padding: clamp(28px, 4vw, 44px) 16px 20px;
  background: rgba(10, 6, 18, 0.5);
  border: 1px solid rgba(176, 38, 255, 0.18);
  border-radius: 4px;
}
.neon-sign__ascii {
  font-family: monospace;
  font-size: clamp(0.66rem, 1.1vw, 0.86rem);
  line-height: 1.25;
  white-space: pre;
  display: inline-block;
  text-align: left;
  margin: 0 0 18px;
}
.neon-sign--magenta .neon-sign__ascii {
  color: var(--neon-magenta);
  text-shadow: 0 0 6px var(--neon-magenta), 0 0 14px rgba(255, 45, 149, 0.45);
  animation: neon-flicker-a 4.1s infinite;
}
.neon-sign--cyan .neon-sign__ascii {
  color: var(--neon-cyan);
  text-shadow: 0 0 6px var(--neon-cyan), 0 0 14px rgba(0, 240, 255, 0.45);
}
.neon-sign--purple .neon-sign__ascii {
  color: var(--neon-purple);
  text-shadow: 0 0 6px var(--neon-purple), 0 0 14px rgba(176, 38, 255, 0.45);
  animation: neon-flicker-c 5.7s infinite;
}
.neon-sign--amber .neon-sign__ascii {
  color: var(--neon-amber);
  text-shadow: 0 0 6px var(--neon-amber), 0 0 14px rgba(255, 176, 0, 0.45);
  animation: neon-flicker-b 3.2s infinite;
}
.neon-sign__cap {
  font-family: var(--neon-font-display);
  font-size: 1.15rem;
  letter-spacing: 0.04em;
  margin: 0 0 6px;
  color: var(--neon-sign-white);
}
.neon-sign__cap :lang(ko) { color: var(--neon-dim); }
.neon-sign__hours {
  font-family: var(--neon-font-latin);
  font-size: 0.68rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--neon-quiet);
  margin: 0;
}

/* ==========================================================================
   Retrowave grid horizon — the city's edge
   ========================================================================== */
.neon-grid-sect {
  position: relative;
  overflow: hidden;
}
.neon-grid {
  position: relative;
  height: clamp(320px, 50vh, 520px);
  margin-top: clamp(20px, 4vh, 40px);
  perspective: 320px;
  perspective-origin: 50% 0%;
  overflow: hidden;
}
.neon-grid__sun {
  position: absolute;
  left: 50%;
  bottom: 42%;
  width: clamp(180px, 28vw, 360px);
  height: clamp(180px, 28vw, 360px);
  transform: translateX(-50%);
  border-radius: 50%;
  background: linear-gradient(180deg, var(--neon-amber) 0%, var(--neon-magenta) 55%, var(--neon-purple) 100%);
  box-shadow: 0 0 80px rgba(255, 45, 149, 0.5), 0 0 160px rgba(176, 38, 255, 0.3);
  -webkit-mask: repeating-linear-gradient(180deg, #000 0 8px, transparent 8px 12px);
  mask: repeating-linear-gradient(180deg, #000 0 8px, transparent 8px 12px);
  opacity: 0.85;
}
.neon-grid__floor {
  position: absolute;
  left: -50%;
  right: -50%;
  bottom: 0;
  height: 60%;
  transform: rotateX(70deg);
  transform-origin: 50% 100%;
  background-image:
    linear-gradient(rgba(0, 240, 255, 0.55) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 45, 149, 0.55) 1px, transparent 1px);
  background-size: 44px 44px;
  background-position: center;
  animation: neon-grid-scroll 4s linear infinite;
  filter: drop-shadow(0 0 6px rgba(0, 240, 255, 0.4));
}
@keyframes neon-grid-scroll {
  to { background-position: 0 44px; }
}
@media (prefers-reduced-motion: reduce) {
  .neon-grid__floor { animation: none; }
}

/* ==========================================================================
   Street poem — the city's voice
   ========================================================================== */
.neon-poem {
  max-width: 640px;
  margin: clamp(60px, 10vh, 110px) auto;
  padding: 0 clamp(20px, 5vw, 60px);
  text-align: center;
}
.neon-poem .neon-eyebrow { text-align: center; }
.neon-poem__body {
  margin: 0;
  font-family: var(--neon-font-display);
  font-size: clamp(1.1rem, 2.4vw, 1.6rem);
  line-height: 1.7;
}
.neon-poem__body p { margin: 0; }
.neon-poem__body p[lang="ko"] {
  color: var(--neon-cyan);
  text-shadow: 0 0 8px rgba(0, 240, 255, 0.4);
}
.neon-poem__body p:not([lang="ko"]) {
  font-family: var(--neon-font-latin);
  font-weight: 400;
  color: var(--neon-dim);
  font-size: 0.82em;
  margin-bottom: 0.9em;
}

/* ==========================================================================
   Footer
   ========================================================================== */
.neon-foot {
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(56px, 10vh, 96px) clamp(20px, 5vw, 60px) clamp(40px, 6vh, 64px);
  text-align: center;
  border-top: 1px solid rgba(176, 38, 255, 0.22);
}
.neon-foot__brand {
  font-family: var(--neon-font-latin);
  font-weight: 900;
  font-size: clamp(1rem, 2vw, 1.4rem);
  letter-spacing: 0.2em;
  margin: 0 0 12px;
  color: var(--neon-magenta);
  text-shadow: 0 0 10px rgba(255, 45, 149, 0.5);
}
.neon-foot__brand :lang(ko) { color: var(--neon-cyan); text-shadow: 0 0 10px rgba(0,240,255,0.5); }
.neon-foot__line {
  font-family: var(--neon-font-kr);
  font-size: 0.86rem;
  color: var(--neon-dim);
  margin: 0 0 18px;
}
.neon-foot__line :lang(ko) { color: var(--neon-quiet); }
.neon-foot__line:not(:lang(ko)) { font-family: var(--neon-font-latin); }
.neon-foot__copy {
  font-family: var(--neon-font-latin);
  font-size: 0.64rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--neon-quiet);
  margin: 0;
}

/* ==========================================================================
   Overlays — rain, scanlines, vignette (fixed, over everything)
   ========================================================================== */
.neon-rain {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    105deg,
    transparent 0px,
    transparent 3px,
    rgba(0, 240, 255, 0.045) 3px,
    rgba(0, 240, 255, 0.045) 4px
  );
  animation: neon-rain 0.6s linear infinite;
}
@keyframes neon-rain { to { background-position: 0 22px; } }
@media (prefers-reduced-motion: reduce) {
  .neon-rain { animation: none; opacity: 0.4; }
}

.neon-scanlines {
  position: fixed;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, 0.16) 2px,
    rgba(0, 0, 0, 0.16) 3px
  );
}

.neon-vignette {
  position: fixed;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background: radial-gradient(
    120% 100% at 50% 40%,
    transparent 50%,
    rgba(5, 3, 10, 0.55) 100%
  );
}

/* ---- Neon flicker keyframes (mutually-prime periods) ---- */
@keyframes neon-flicker-a {
  0%, 19%, 21%, 23%, 25%, 54%, 56%, 100% { opacity: 1; }
  20%, 24%, 55% { opacity: 0.55; }
  22% { opacity: 0.85; }
}
@keyframes neon-flicker-b {
  0%, 32%, 34%, 70%, 72%, 100% { opacity: 1; }
  33%, 71% { opacity: 0.6; }
}
@keyframes neon-flicker-c {
  0%, 47%, 49%, 81%, 83%, 100% { opacity: 1; }
  48%, 82% { opacity: 0.5; }
}
@keyframes neon-win-blink {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 0.25; }
}
@media (prefers-reduced-motion: reduce) {
  .neon-title__glow,
  .neon-hang,
  .neon-sign__ascii,
  .neon-win { animation: none; }
}

/* ==========================================================================
   Responsive
   ========================================================================== */
@media (max-width: 720px) {
  .neon-scene { height: 300px; margin: 0 4px; }
  .neon-hang { font-size: 1.2rem; }
  .neon-signgrid { grid-template-columns: 1fr 1fr; }
  .neon-poem__body { font-size: 1rem; }
}
@media (max-width: 440px) {
  .neon-signgrid { grid-template-columns: 1fr; }
}
